					file={file}
					messages={messages}
					onDownload={onDownload}
				/>
			) : (
				<object
					aria-label={objectProps?.['aria-label'] ?? messages.pdfLabel(file)}
					{...objectProps}
					className={cn('min-h-96 w-full flex-1', objectProps?.className)}
					data={src}
					onError={(event) => {
						setFailedSrc(src);
						objectProps?.onError?.(event);
					}}
					type='application/pdf'
